// sketch.js

// How many clusters across / down
const CLUSTERS_X = 4;
const CLUSTERS_Y = 3;

// Within each cluster: how many circles per row / column
const CIRCLES_PER_CLUSTER = 7;

// Diameter of each circle
const CIRCLE_DIAMETER = 40;

// Spacing between adjacent circles (in a grid)
const INNER_SPACING = 8;

// Extra gap between clusters (outer black border)
const CLUSTER_GAP = 24;

// A small palette of bluish/teal/pink/red tones
let palette = ["#E40303", "#FF8C00", "#FFED00", "#008026", "#24408E", "#732982"];

let palette1 = [
  "#B3E5FC", // very light cyan
  "#40C4FF", // bright sky blue
  "#03A9F4", // deeper blue
  "#1DE9B6", // light teal
  "#C51162", // magenta/pink
  "#F50057", // pinkish
  "#D50000", // red
  "#B2EBF2", // pale aqua
  "#01579B"  // dark blue
];

function setup() {
  // Create canvas roughly the same aspect ratio as your photo
  createCanvas(innerWidth, innerHeight);
	describe("colored circles in grids, inspired by Berlin Philharmonie");
	frameRate(30);
  loop();
}

function draw() {
  background(0);
  noStroke();

  // Compute the size (in pixels) of one full cluster (including its own inner spacing)
  //   7 circles × diameter  +  6 gaps × INNER_SPACING
  const clusterSize = CIRCLES_PER_CLUSTER * CIRCLE_DIAMETER
                    + (CIRCLES_PER_CLUSTER - 1) * INNER_SPACING;

  // Loop over each cluster row/column
  for (let cy = 0; cy < CLUSTERS_Y; cy++) {
    for (let cx = 0; cx < CLUSTERS_X; cx++) {
      // Top-left corner of this cluster’s “bounding box”
      const clusterX = cx * (clusterSize + CLUSTER_GAP) + CLUSTER_GAP / 2;
      const clusterY = cy * (clusterSize + CLUSTER_GAP) + CLUSTER_GAP / 2;

      // Now draw a 7×7 grid of circles “inside” this cluster.
      // We’ll stagger every other row by half a diameter.
      for (let row = 0; row < CIRCLES_PER_CLUSTER; row++) {
        for (let col = 0; col < CIRCLES_PER_CLUSTER; col++) {
          // Horizontal offset: if this is an “odd” row, shift right by half a diameter
          let xOffset = (row % 2 === 1) ? (CIRCLE_DIAMETER / 2) : 0;

          // Compute center‐x and center‐y of each circle
          let x = clusterX
                + xOffset
                + col * (CIRCLE_DIAMETER + INNER_SPACING);

          let y = clusterY
                + row * (CIRCLE_DIAMETER + INNER_SPACING);

          // Pick a random color from our palette
          fill(random(palette));
					const ns = noise((x/CLUSTERS_X)/CIRCLES_PER_CLUSTER, y/CLUSTERS_Y/CIRCLES_PER_CLUSTER, frameCount/120)
					fill(palette[~~(ns*2*palette.length)%palette.length])
          nedge(x, y, CIRCLE_DIAMETER, CIRCLE_DIAMETER, 6, PI/6);
        }
      }
    }
  }

	// // noLoop() removed for animation
}

function nedge(cx, cy, dx, dy, n, da = 0) {
	// ellipse(cx, cy, dx, dy)
	beginShape()
	for (let i = 0; i < n; i++) {
		const a = i / n * TAU;
		var x = cos(a+da) * dx / 2 + cx;
		var y = sin(a+da) * dy / 2 + cy;
		vertex(x, y);
	}
	endShape(CLOSE);
}

function mouseClicked() {
	if (mouseButton != RIGHT) setup();
}
